Given an array arr[], for each element, find the first element to its right that appears more times in the array than the current element. If no such element exists, assign -1.Examples: Input: arr[] = [2, 1, 1, 3, 2, 1]Output: [1, -1, -1, 2, 1, -1] Explanation: Frequencies: 1 → 3 times, 2 → 2 times, 3 → 1 time. For arr[0] = 2, the next element 1 has a higher frequency → 1. For arr[1] and arr[2] (1), no element to the right has a higher frequency → -1. For arr[3] = 3, the next 2 has a higher frequency → 2. For arr[4] = 2, the next 1 has a higher frequency → 1. For arr[5] = 1, no elements to the right → -1.Input: arr[] = [1, 2, 1]Output: [-1, 1, -1]Explanation: Frequencies: 1 → 2, 2 → 1. 2→1 (higher freq), others have no higher freq on right → [-1, 1, -1]Try It YourselfTable of Content[Naive approach] Frequency Count and Nested Loop - O(n^2) Time and O(n) Space[Efficient Approach] Frequency Counting and Stack - O(n) Time and O(n) Space[Naive approach] Frequency Count and Nested Loop - O(n2) Time and O(n) SpaceThe idea is to find, for each element, the next element to its right that has a higher frequency using a frequency map and a nested loop. If none exists, return -1.
            C++

    #include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

vector<int> nextFreqGreater(vector<int>& arr) {

    // calculate frequency of each element
    // using a hash map (unordered_map).
    unordered_map<int, int> freq;
    for (int num : arr) {
        freq[num]++;
    }

    vector<int> result;

    for (int i = 0; i < arr.size(); i++) {
        bool found = false;

        // inner loop to find the first element 
        // with a greater frequency
        for (int j = i + 1; j < arr.size(); j++) {
            if (freq[arr[j]] > freq[arr[i]]) {
                result.push_back(arr[j]);
                found = true;
                break;
            }
        }

        // if no element with a greater frequency 
        // is found, push -1
        if (!found) {
            result.push_back(-1);
        }
    }

    return result;
}

int main() {
    vector<int> arr = {2, 1, 1, 3, 2, 1}; 
    vector<int> result = nextFreqGreater(arr); 


    for (int num : result) {
        cout << num << " ";
    }
    cout << endl;

    return 0;
}


