[Efficient Approach] Frequency Counting and Stack - O(n) Time and O(n) SpaceThe idea is to use a frequency map to count occurrences, then apply a stack-based approach (similar to "Next Greater Element") to efficiently find the next element with a higher frequency for each position. For each element, we compare its frequency with elements tracked in the stack and update the result when a higher frequency is found.
            C++

    #include <iostream>
#include <stack>
#include <vector>
#include <unordered_map>

using namespace std;

vector<int> nextFreqGreater(vector<int>& arr) {
    int n = arr.size();
    unordered_map<int, int> freq;

    // Building Frequency Map
    for (int i = 0; i < arr.size(); ++i) {
        freq[arr[i]]++;
    }

    vector<int> res(n, -1);    
    stack<int> st;              

    for (int i = 0; i < n; i++) {

        // While current frequency is 
        // greater than frequency at stack top
        while (!st.empty() && freq[arr[i]] > 
                        freq[arr[st.top()]]) {
            res[st.top()] = arr[i];
            st.pop();
        }
        st.push(i);
    }

    return res;
}

int main() {
    vector<int> arr = {2, 1, 1, 3, 2, 1};
    vector<int> result = nextFreqGreater(arr);

    for (int x : result) {
        cout << x << " ";
    }

    return 0;
}


